mapper.select:
select 
from biz_pay_order o
left join biz_member m on m.member_id = o.member_id
left join biz_pay_provider p on p.provider_code = o.provider_code
left join biz_pay_channel c on c.channel_code = o.channel_code

    and o.member_id = #{memberId}
    and o.out_trade_no = #{outTradeNo}
    and o.provider_code = #{providerCode}
    and o.channel_code = #{channelCode}
    and o.status = #{status}
    and m.phone like concat('%', #{phone}, '%')
    and o.create_time >= #{params.beginTime}
    and o.create_time < date_add(#{params.endTime}, interval 1 day)

order by o.pay_order_id desc

mapper.insert:
insert into biz_pay_order (
    out_trade_no, recharge_id, member_id, provider_code, channel_code, product_id,
    currency, amount, provider_amount, status, pay_type, pay_url, provider_trade_no,
    expire_time, create_time, remark
) values (
    #{outTradeNo}, #{rechargeId}, #{memberId}, #{providerCode}, #{channelCode}, #{productId},
    #{currency}, #{amount}, #{providerAmount}, #{status}, #{payType}, #{payUrl}, #{providerTradeNo},
    #{expireTime}, sysdate(), #{remark}
)

mapper.update:
update biz_pay_order
status = #{status}, pay_type = #{payType}, pay_url = #{payUrl}, provider_trade_no = #{providerTradeNo}, notify_payload = #{notifyPayload}, paid_time = #{paidTime}, remark = #{remark}, update_time = sysdate()
where pay_order_id = #{payOrderId}
